create table if not exists "posts" (
    "ID" bigint generated by default as identity primary key,
    "TITLE" varchar(255)
);

create table if not exists "resource_subjects" (
    "ID" bigint generated by default as identity primary key,
    "RESOURCE" varchar(255),
    "RESOURCE_ID" bigint,
    "SUBJECT_TYPE" varchar(64),
    "SUBJECT_ID" varchar(64)
);
